// English File Intermediate Plus: text practice for all 12 supplied banks,
// with separate picture datasets as verified visuals become available.
const ACCENT = "#c4c47f";

// Add a bank's slug here after its assets and activities are ready for students.
export const INTERMEDIATE_PLUS_PUBLISHED_BANKS = ["adjective-suffixes", "packing"];

function slug(value) {
  return value.toLowerCase().replace(/['’]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

// A row contains a target, its meaning, its subtopic, and optional accepted variants.
function vocabulary(bank, rows) {
  return rows.map(([term, meaning, category, acceptedAnswers = []]) => ({
    id: `intplus-${bank}-${slug(term)}`,
    term,
    meaning,
    category,
    flashcardPrompt: meaning,
    flashcardAnswer: term,
    flashcardNote: category,
    matchPrompt: meaning,
    matchAnswer: term,
    acceptedAnswers,
  }));
}

// Context rows: sentence/clue, answer, explicit distractors, explanation, variants.
function questions(bank, rows) {
  return rows.map(([sentence, answer, distractors = [], explanation = "", acceptedAnswers = []], index) => ({
    id: `intplus-${bank}-${index + 1}`,
    sentence,
    answer,
    options: [answer, ...distractors],
    explanation,
    acceptedAnswers,
  }));
}

function choice(id, title, dataKey, shortDescription, question = "Which word or phrase fits?") {
  return { id, type: "sentence-gap-choice", title, dataKey, shortDescription, prompt: shortDescription, question, itemLimit: 12 };
}

function write(id, title, dataKey, shortDescription) {
  return { id, type: "sentence-gap-type-answer", title, dataKey, shortDescription, prompt: shortDescription, question: "Type the missing word or phrase.", itemLimit: 12 };
}

function sort(id, title, dataKey, categories, shortDescription, promptKey = "term") {
  return {
    id, type: "category-sort", title, dataKey, categories: categories.map((label) => ({ id: label, label })),
    shortDescription, prompt: shortDescription, promptKey, itemLimit: 15,
  };
}

function bank(id, order, title, shortDescription, entries, datasets, activities, infoNotes, { matchingActivity, includeMeaningActivities = true } = {}) {
  return {
    id: `b1-b2-${id}`, level: "b1-b2", order, title, shortDescription,
    studentVisible: INTERMEDIATE_PLUS_PUBLISHED_BANKS.includes(id),
    textbookRef: `Intermediate Plus Vocabulary Bank ${order}`, accent: ACCENT,
    itemCount: entries.length, entries, ...datasets, infoNotes,
    activities: [
      ...(includeMeaningActivities ? [
        { id: "meaning-flashcards", type: "flashcards", title: "Meaning flashcards", shortDescription: "Recall the word or phrase from its meaning.", prompt: "Read the meaning, say the word or phrase, then flip to check.", itemLimit: 15 },
        matchingActivity || { id: "meaning-matching", type: "matching", title: "Match words and meanings", shortDescription: "Match each clue with the correct word or phrase.", prompt: "Match the meanings on the left with the words or phrases on the right.", uniqueMatchAnswerKey: "matchAnswer", itemLimit: 6 },
      ] : []),
      ...activities,
    ],
  };
}

